import json,re
from pathlib import Path
L=json.loads(Path('dist/lessons.json').read_text())
def A(t,ut,g,d,du,seq,body,h='',pre=''):
 steps=[]
 for i,p in enumerate(re.split(r'(?<=۔)\|',seq)):
  en,ur=p.rsplit('~',1);steps.append(dict(title=['Start with the idea','Apply the rule','Follow the result'][i],en=en,ur=ur))
 code='#include <iostream>\n'+''.join('#include <'+x+'>\n' for x in h.split())+'\n'+(pre+'\n\n' if pre else '')+'int main() {\n'+'\n'.join('    '+x for x in body.split('\n'))+'\n}\n'
 L.append(dict(id=len(L)+1,title=t,ur=ut,group=g,definition=d,definitionUr=du,explanation=' '.join(s['en'] for s in steps),urdu=' '.join(s['ur'] for s in steps),steps=steps,code=code,takeaway=steps[-1]['en'],practice='Change one value in this example and explain how the output changes.',tags=t+' '+ut,minutes=7,overview=False,source='V3school · Focused reference lesson',prerequisites='Read Your first C++ program and Variables & data types first.'))
A('int: whole numbers','پورے اعداد','2. Foundations','int is a signed integer type for whole-number arithmetic.','int پورے مثبت اور منفی اعداد کی ٹائپ ہے۔','Choose int when fractions are not needed. Its exact range depends on the implementation.~اعشاری حصہ نہ چاہیے تو int لیں؛ حد پلیٹ فارم پر منحصر ہے۔|Initialize apples to 7, then subtract 2 using ordinary integer arithmetic.~apples سات ہے، دو کم کریں۔|The result is 5. Signed overflow is undefined behavior, so do not assume arithmetic always wraps.~جواب پانچ ہے؛ signed عدد کی حد پار کرنا غیر معین رویہ ہے۔','int apples{7};\napples -= 2;\nstd::cout << apples;')
A('double: decimal numbers','اعشاری اعداد','2. Foundations','double is a floating-point type that approximates real-number values.','double اعشاری اعداد کی تقریبی نمائندگی کرتا ہے۔','Use double for quantities such as temperature or distance with fractions.~اعشاری مقدار جیسے درجہ حرارت کے لیے double لیں۔|The division uses a floating-point operand, so it preserves a fractional result.~double کی تقسیم اعشاری نتیجہ دیتی ہے۔|The output is 2.5. Many decimal fractions are not represented exactly, so use suitable tolerances when comparing measured results.~یہاں 2.5 ہے؛ بہت سے اعشاری اعداد بالکل درست محفوظ نہیں ہوتے۔','double distance{5.0};\nstd::cout << distance / 2.0;')
A('char: character values','حرف کی قدر','2. Foundations','char is a small integral type commonly used for one code unit of text.','char متن کا ایک چھوٹا کوڈ یونٹ رکھنے کی ٹائپ ہے۔','Use single quotes for a character literal, such as A; double quotes create a string literal.~ایک حرف کے لیے single quotes اور متن کے لیے double quotes ہیں۔|A char stores an encoded value, which cout normally displays as a character.~char کو cout عموماً حرف کی صورت دکھاتا ہے۔|One char does not generally hold a full Urdu character in UTF-8; use a string for such text.~UTF-8 اردو کا مکمل حرف عموماً ایک char میں نہیں آتا، string لیں۔',"char grade{'A'};\nstd::cout << grade;")
A('bool: true and false','درست اور غلط','2. Foundations','bool represents one of two logical values: true or false.','bool صرف true یا false رکھتا ہے۔','A comparison produces a Boolean result instead of modifying its operands.~موازنہ Boolean نتیجہ دیتا ہے، اعداد نہیں بدلتا۔|18 >= 18 evaluates to true and initializes eligible.~18 >= 18 درست ہے، eligible میں true آتا ہے۔|boolalpha displays true instead of the default numeric representation 1.~boolalpha عدد 1 کی جگہ true دکھاتا ہے۔','bool eligible = 18 >= 18;\nstd::cout << std::boolalpha << eligible;')
A('const: read-only objects','ناقابلِ تبدیلی آبجیکٹ','2. Foundations','const prevents modification through the const-qualified object or access path.','const کے ذریعے اس آبجیکٹ یا رسائی کے راستے سے تبدیلی منع ہوتی ہے۔','Give the const object its value during initialization.~const کو ابتدا میں قدر دیں۔|Read the value normally in calculations or output.~اسے حساب یا آؤٹ پٹ میں پڑھ سکتے ہیں۔|Assigning a new value to limit would be a compile error. const does not always mean the value was computed at compile time.~بعد میں limit بدلنا خرابی ہے؛ const ہمیشہ compile-time حساب نہیں۔','const int limit{10};\nstd::cout << limit;')
A('Comments','کوڈ کے تبصرے','2. Foundations','Comments explain source code to people and do not execute as program statements.','تبصرہ انسان کو کوڈ سمجھاتا ہے، پروگرام کا عمل نہیں بنتا۔','Use // for the rest of a line.~// باقی لائن کا تبصرہ ہے۔|Use /* and */ around a block comment. Ordinary block comments cannot be nested.~بلاک کے لیے /* */ لیں؛ عام بلاک تبصرہ اندر اندر نہ بنائیں۔|The compiler ignores the comments while compiling the output statement.~کمپائلر تبصرہ چھوڑ کر اصل بیان کمپائل کرتا ہے۔','// A message for the learner\n/* This comment does not print. */\nstd::cout << "Welcome";')
A('Identifiers & naming','نام رکھنے کے اصول','2. Foundations','An identifier is a name for a program entity such as a variable, function or type.','identifier متغیر، فنکشن یا ٹائپ کا نام ہے۔','Choose a descriptive name such as totalMarks rather than a vague single letter.~واضح نام totalMarks جیسا لیں۔|Names are case-sensitive: totalMarks and totalmarks are different names.~بڑے چھوٹے حروف سے نام بدل جاتا ہے۔|Avoid reserved keywords and reserved implementation names, especially double underscores.~keywords اور double underscore والے محفوظ نام نہ لیں۔','int totalMarks{90};\nstd::cout << totalMarks;')
A('std::cout','سکرین پر آؤٹ پٹ','2. Foundations','std::cout is the standard output stream used to write formatted console output.','std::cout عام آؤٹ پٹ سٹریم ہے جو متن اور قدریں دکھاتا ہے۔','Include iostream to make the stream declarations available.~iostream ہیڈر شامل کریں۔|Each << inserts the next value into the same stream, so operations can be chained.~ہر << اگلی قدر اسی سٹریم میں ڈالتا ہے۔|The literal text and variable value appear together; a newline is explicit rather than automatic.~متن اور قدر ساتھ دکھتے ہیں؛ نئی لائن خود نہیں آتی۔','int score{95};\nstd::cout << "Score: " << score << "\\n";')
A('std::cin','کی بورڈ ان پٹ','2. Foundations','std::cin is the standard input stream for extracting typed values.','std::cin ان پٹ سے مخصوص ٹائپ کی قدر پڑھتا ہے۔','Prepare a destination with the expected type.~مطلوبہ ٹائپ کا متغیر بنائیں۔|Extraction skips leading whitespace for an integer and tries to parse a number.~عدد پڑھتے وقت ابتدائی خالی جگہ چھوڑ کر عدد بنایا جاتا ہے۔|Always check extraction success before using the destination as user input.~صارف کی قدر استعمال کرنے سے پہلے کامیابی چیک کریں۔','int age{};\nif (std::cin >> age) std::cout << "Next year: " << age + 1;\nelse std::cout << "Invalid age";')
A('std::getline','پوری لائن پڑھنا','7. Arrays & strings','std::getline reads characters up to a delimiter, usually a newline, into a string.','getline نئی لائن تک پورا متن string میں پڑھتا ہے۔','Use a string when spaces may be part of the input.~ان پٹ میں خالی جگہ ہو تو string لیں۔|getline stores the line but discards its terminating newline.~متن رکھتا ہے مگر آخری newline نہیں رکھتا۔|After a prior >> extraction, handle the leftover newline deliberately before calling getline.~پہلے >> چلا ہو تو بچی newline سنبھالیں۔','std::string name;\nif (std::getline(std::cin, name)) std::cout << "Hello, " << name;','string')
A('Arithmetic operators','حساب کے آپریٹر','2. Foundations','Arithmetic operators calculate sums, differences, products, quotients and remainders.','حسابی آپریٹر جمع، تفریق، ضرب، تقسیم اور باقی دیتے ہیں۔','+ and - add or subtract; * multiplies. Operand types affect the result.~جمع، تفریق اور ضرب کا نتیجہ ٹائپ پر بھی منحصر ہے۔|For integers, / truncates the quotient toward zero and % gives the remainder.~integer تقسیم صفر کی سمت کٹتی ہے اور % باقی دیتا ہے۔|7/2 is 3 and 7%2 is 1. Division by zero is invalid for integer operands.~سات تقسیم دو تین اور باقی ایک ہے؛ صفر سے integer تقسیم غلط ہے۔','std::cout << 7 / 2 << " " << 7 % 2;')
A('Logical operators','منطقی آپریٹر','3. Control flow','Logical operators combine or negate Boolean conditions.','منطقی آپریٹر شرائط کو ملاتے یا الٹتے ہیں۔','&& needs both conditions true; || needs at least one; ! reverses the Boolean result.~&& دونوں، || کم از کم ایک شرط مانگتا ہے اور ! الٹتا ہے۔|Built-in && and || short-circuit: the right operand is evaluated only when needed.~دائیں شرط صرف ضرورت پر چلتی ہے۔|Use short-circuit checks to guard operations such as division by a potentially zero value.~ممکنہ صفر سے تقسیم کو پہلے شرط سے روکیں۔','int divisor{2};\nbool safe = divisor != 0 && 10 / divisor > 1;\nstd::cout << std::boolalpha << safe;')
A('if and else','اگر اور ورنہ','3. Control flow','if selects a branch according to a condition; else supplies the alternative branch.','if شرط کے مطابق شاخ چنتا ہے، else دوسری صورت ہے۔','Evaluate the comparison once at the decision point.~فیصلے کے مقام پر شرط دیکھیں۔|If true, execute the first block; otherwise execute the else block.~درست ہو تو پہلا، ورنہ دوسرا بلاک چلائیں۔|Execution rejoins after the conditional. Braces make which statements belong to each branch clear.~بعد میں راستے مل جاتے ہیں؛ بریس بلاک کی حد واضح کرتی ہے۔','int age{17};\nif (age >= 18) { std::cout << "Adult"; }\nelse { std::cout << "Under 18"; }')
A('switch statements','سوئچ بیان','3. Control flow','switch chooses a labeled branch based on an integral or enum expression.','switch عدد یا enum کی قدر سے case منتخب کرتا ہے۔','Evaluate the selector and find a matching constant case label.~قدر دیکھ کر مستقل case تلاش کریں۔|Execute from that label. Without break, control can continue into later cases.~case کے بعد break نہ ہو تو اگلا بھی چل سکتا ہے۔|default handles unmatched values; break exits the switch, not an enclosing function.~default باقی قدریں سنبھالتا اور break صرف switch چھوڑتا ہے۔','int choice{2};\nswitch (choice) {\ncase 1: std::cout << "Tea"; break;\ncase 2: std::cout << "Water"; break;\ndefault: std::cout << "Unknown";\n}')
A('for loops','فار لوپ','3. Control flow','A for loop combines initialization, a continuation test and an update expression.','for ابتدا، شرط اور تبدیلی ایک جگہ رکھتا ہے۔','Initialize i once before the first test.~i کو صرف ابتدا میں بنائیں۔|Test i <= 3 before each body execution.~ہر چکر سے پہلے شرط دیکھیں۔|Run ++i after the body, then repeat the test; the output is 1 2 3.~body کے بعد بڑھائیں؛ نتیجہ 1 2 3 ہے۔','for (int i = 1; i <= 3; ++i) std::cout << i << " ";')
A('while loops','وائل لوپ','3. Control flow','while repeats a body only while its condition is true before an iteration.','while ہر چکر سے پہلے شرط درست ہو تو چلتا ہے۔','Set the starting state outside the loop.~ابتدائی حالت باہر دیں۔|The condition can be false immediately, giving zero executions.~پہلی شرط غلط ہو تو body ایک بار بھی نہیں چلتی۔|Update the state in the body so the loop eventually stops.~body میں تبدیلی کریں تاکہ لوپ رک سکے۔','int remaining{3};\nwhile (remaining > 0) { std::cout << remaining << " "; --remaining; }')
A('do-while loops','ڈو وائل لوپ','3. Control flow','do-while tests its continuation condition after executing the body.','do-while body کے بعد شرط دیکھتا ہے۔','Enter the body before any loop condition check.~شرط سے پہلے body چلتی ہے۔|The body therefore executes at least once, even with a false initial condition.~ابتدائی شرط غلط ہو تب بھی ایک بار چلتی ہے۔|The closing while(condition); needs a semicolon.~آخر کے while کے بعد سیمی کولن ضروری ہے۔','int n{0};\ndo { std::cout << "Once"; } while (n > 0);')
A('break and continue','بریک اور کنٹینیو','3. Control flow','break exits a loop; continue skips the remainder of the current iteration.','break لوپ چھوڑتا اور continue موجودہ چکر کا باقی حصہ چھوڑتا ہے۔','Use continue when one element should be skipped.~ایک عنصر چھوڑنے کے لیے continue لیں۔|Use break when the whole nearest loop should end.~پورا قریب ترین لوپ ختم کرنا ہو تو break لیں۔|In a for loop, continue still performs the update expression before testing again.~for میں continue کے بعد update پھر شرط چلتی ہے۔','for (int i=1;i<=6;++i) {\n    if (i==2) continue;\n    if (i==5) break;\n    std::cout << i << " ";\n}')
A('Scope & local variables','سکوپ اور مقامی متغیر','5. Functions','Scope is the region where a name can be used to refer to its declaration.','سکوپ وہ حصہ ہے جہاں اعلان کا نام استعمال ہوتا ہے۔','A variable declared inside braces normally has block scope.~بریس میں متغیر اسی بلاک کا نام ہے۔|A nested declaration can hide an outer name without modifying the outer object.~اندر کا نام باہر والے کو چھپاتا ہے، اصل نہیں بدلتا۔|Leaving the inner block restores visibility of the outer declaration.~اندرونی بلاک ختم ہو تو باہر والا نام پھر نظر آتا ہے۔','int x{1};\n{ int x{2}; std::cout << x << " "; }\nstd::cout << x;')
A('Pass by value','قدر کی کاپی پاس کرنا','5. Functions','A value parameter is a separate object initialized from the argument.','ویلیو پیرامیٹر آرگومنٹ سے بننے والا الگ آبجیکٹ ہے۔','Calling change(score) initializes n from score.~score کی قدر n میں آتی ہے۔|Assigning n changes only the function parameter.~n بدلنے سے صرف پیرامیٹر بدلتا ہے۔|score remains 5 after the call because no reference to it was passed.~اصل ریفرنس نہیں دیا، اس لیے score پانچ رہتا ہے۔','int score{5};\nchange(score);\nstd::cout << score;','', 'void change(int n) { n=99; std::cout << n << " "; }')
A('Pass by reference','ریفرنس پاس کرنا','5. Functions','A reference parameter aliases the caller’s object instead of creating a value copy.','ریفرنس پیرامیٹر caller کے اصل آبجیکٹ کا نام ہے۔','int& n binds to score when the function is called.~int& n اصل score سے جڑتا ہے۔|Assignment through n therefore modifies score.~n کے ذریعے assignment اصل score بدلتی ہے۔|Use const int& when modification must not be allowed through this parameter.~تبدیلی منع کرنی ہو تو const ریفرنس لیں۔','int score{5};\nchange(score);\nstd::cout << score;','', 'void change(int& n) { n=99; }')
A('Function overloading','فنکشن اوور لوڈنگ','5. Functions','Function overloading provides multiple functions with one name and different parameter lists.','اوور لوڈنگ میں ایک نام مگر مختلف پیرامیٹر ہوتے ہیں۔','Declare alternatives for the types you want to accept.~مطلوبہ ٹائپس کے لیے الگ صورتیں بنائیں۔|The compiler uses argument types and conversion rules to choose a viable best match.~کمپائلر آرگومنٹ سے بہترین مناسب صورت چنتا ہے۔|Different return types alone cannot distinguish two overloads with the same parameter list.~صرف return type بدلنے سے الگ overload نہیں بنتا۔','show(7);\nshow(2.5);','', 'void show(int x){std::cout << "int " << x << "\\n";}\nvoid show(double x){std::cout << "double " << x << "\\n";}')
A('Default arguments','ڈیفالٹ آرگومنٹ','5. Functions','A default argument supplies a value when the caller omits that trailing argument.','آخری آرگومنٹ نہ دیا جائے تو ڈیفالٹ قدر آتی ہے۔','Specify the default in a visible declaration, usually the header.~ڈیفالٹ نظر آنے والے اعلان، عموماً ہیڈر میں دیں۔|An omitted argument uses that default at the call site.~کال میں قدر چھوڑنے پر ڈیفالٹ آتا ہے۔|An explicitly supplied argument wins; defaults should follow required parameters.~دی ہوئی قدر ترجیح رکھتی ہے؛ ڈیفالٹ لازمی پیرامیٹر کے بعد ہوں۔','greet();\ngreet(3);','', 'void greet(int times=1){for(int i=0;i<times;++i)std::cout<<"Hi ";}')
A('Recursion','خود کو بلانے والا فنکشن','5. Functions','Recursion solves a problem by calling the same function on a smaller subproblem.','ریکریشن فنکشن کو چھوٹے مسئلے پر دوبارہ بلاتا ہے۔','Define a base case that returns without another recursive call.~ایسی رکنے کی شرط لکھیں جو مزید کال نہ کرے۔|Move toward it on each recursive call.~ہر کال اس شرط کے قریب جائے۔|Combine returned results; large recursion depth can exhaust stack space.~واپس نتائج ملائیں؛ بہت گہرائی سٹیک بھر سکتی ہے۔','std::cout << sumTo(4);','', 'int sumTo(int n){if(n<=0)return 0;return n+sumTo(n-1);}')
A('Access control: public and private','پبلک اور پرائیویٹ','6. Objects & classes','Access control restricts which code may name class members.','رسائی کے اصول طے کرتے ہیں کون رکن استعمال کر سکتا ہے۔','Keep invariant-sensitive state private.~اہم حالت private رکھیں۔|Expose public operations that maintain those invariants.~public عمل حالت درست رکھیں۔|A caller can read balance() but cannot directly assign the private amount.~caller balance پڑھ سکتا مگر amount سیدھا نہیں بدل سکتا۔','Account a;\nstd::cout << a.balance();','', 'class Account {int amount{100}; public: int balance() const{return amount;}};')
A('Constructors','آبجیکٹ کی ابتدا','6. Objects & classes','A constructor initializes an object when its lifetime begins.','کنسٹرکٹر آبجیکٹ کی زندگی شروع ہونے پر ابتدا کرتا ہے۔','A constructor has the class name and no return type.~نام کلاس والا اور return type نہیں ہوتا۔|A member initializer list initializes members before the body executes.~initializer list body سے پہلے ارکان بناتی ہے۔|The initialized object starts in a valid, usable state.~بننے والا آبجیکٹ درست حالت میں ہوتا ہے۔','Student s{80};\nstd::cout << s.score;','', 'struct Student {int score; explicit Student(int n):score(n){}};')
A('Destructors','آبجیکٹ کی صفائی','6. Objects & classes','A destructor runs as part of ending an object’s lifetime.','ڈسٹرکٹر آبجیکٹ کی زندگی ختم کرتے وقت چلتا ہے۔','Its name is the class name prefixed with ~.~نام سے پہلے ~ لکھتے ہیں۔|An automatic local object is destroyed when its scope is left normally or during exception unwinding.~مقامی آبجیکٹ سکوپ چھوڑنے پر ختم ہوتا ہے۔|Prefer resource-owning members; their destructors clean up automatically after the enclosing destructor body.~وسائل والے ارکان خود صفائی کرتے ہیں۔','{ Notice n; std::cout << "Inside "; }\nstd::cout << "Outside";','', 'struct Notice {~Notice(){std::cout<<"Destroyed ";}};')
A('Copy constructors','کاپی کنسٹرکٹر','6. Objects & classes','A copy constructor initializes a new object from an existing object of the same type.','کاپی کنسٹرکٹر ایک آبجیکٹ سے اسی ٹائپ کا نیا آبجیکٹ بناتا ہے۔','Box b=a creates b; it is initialization rather than assignment to an existing b.~b=a نیا b بناتا ہے، پہلے موجود b میں assignment نہیں۔|The default copy constructor copies each base and member according to its own copying rules.~خودکار کاپی ہر رکن کے اپنے اصول سے ہوتی ہے۔|Raw owning pointers need special care; using a string member safely copies the owned text.~خام مالک پوائنٹر احتیاط چاہتا ہے، string صحیح متن کاپی کرتی ہے۔','Box a{"hello"};\nBox b=a;\nb.text="changed";\nstd::cout << a.text;','string','struct Box {std::string text;};')
A('Static class members','کلاس کا مشترک رکن','6. Objects & classes','A static data member belongs to the class rather than to each individual object.','static رکن ہر آبجیکٹ کے بجائے کلاس کا مشترک حصہ ہے۔','Declare one shared count using inline static in this C++17 example.~inline static سے ایک مشترک گنتی بنائیں۔|Each constructor increments the same count.~ہر کنسٹرکٹر اسی عدد کو بڑھاتا ہے۔|Counter::created reads the class member without requiring an object expression.~کلاس کے نام سے مشترک عدد پڑھیں۔','Counter a,b;\nstd::cout << Counter::created;','', 'struct Counter {inline static int created=0; Counter(){++created;}};')
A('Const member functions','کانسٹ ممبر فنکشن','6. Objects & classes','A const member function cannot modify ordinary members through its this pointer.','const ممبر فنکشن اپنے this سے عام ارکان نہیں بدل سکتا۔','Put const after the function parameter list.~پیرامیٹر کے بعد const لکھیں۔|This makes the operation callable on a const object.~اب const آبجیکٹ پر بھی کال ہو سکتی ہے۔|Constness is not deep immutability of all referenced objects; design the interface carefully.~یہ ہر متعلقہ آبجیکٹ کی مکمل تبدیلی روکنے کی ضمانت نہیں۔','const Box b{9};\nstd::cout << b.get();','', 'struct Box {int value; int get() const{return value;}};')
A('The this pointer','موجودہ آبجیکٹ کا پوائنٹر','11. Polymorphism','this is the pointer to the object on which a non-static member function is invoked.','this وہ پوائنٹر ہے جس آبجیکٹ پر ممبر فنکشن چلا ہے۔','Each call on a different object has the corresponding this pointer.~ہر آبجیکٹ کی کال میں اسی کا this ہوتا ہے۔|Use this->value to distinguish a member from a same-named parameter.~ایک نام کے پیرامیٹر سے رکن الگ کرنے کے لیے this->value لیں۔|Returning *this can support method chaining when the reference remains valid.~درست زندگی کے دوران *this واپس دے کر chaining کر سکتے ہیں۔','Box b;\nb.set(8);\nstd::cout << b.value;','', 'struct Box {int value{}; Box& set(int value){this->value=value;return *this;}};')
A('Inheritance: public base classes','پبلک وراثت','9. Inheritance','Public inheritance allows a derived object to be used through its accessible base interface.','پبلک وراثت ڈیرائیوڈ آبجیکٹ کو بیس انٹرفیس سے استعمال کرنے دیتی ہے۔','Put the common contract in the base class.~مشترک عمل بیس میں رکھیں۔|Derive publicly when the derived type can honor that contract.~پبلک وراثت تب دیں جب نئی قسم وہ وعدہ پورا کرے۔|Private base state stays inaccessible to the derived class unless exposed through an interface.~نجی بیس ڈیٹا خود بخود ڈیرائیوڈ کو نہیں ملتا۔','Dog d;\nconst Animal& a=d;\na.eat();','', 'struct Animal {void eat() const{std::cout<<"Eating";}};\nstruct Dog:public Animal {};')
A('Composition','آبجیکٹ کے اندر آبجیکٹ','9. Inheritance','Composition builds a type by storing other objects as its members.','کمپوزیشن میں دوسری ٹائپس کے آبجیکٹ رکن بنتے ہیں۔','A Car has an Engine, rather than being an Engine.~Car انجن رکھتی ہے، خود انجن نہیں۔|The containing object manages the member lifetime automatically.~باہر کا آبجیکٹ رکن کی زندگی سنبھالتا ہے۔|Delegate work to the member to reuse behavior without an inheritance relationship.~وراثت کے بغیر رکن کو کام دے کر عمل استعمال کریں۔','Car c;\nc.start();','', 'struct Engine{void start(){std::cout<<"Engine on";}};\nstruct Car{Engine engine;void start(){engine.start();}};')
A('Abstract classes','ایبسٹریکٹ کلاس','11. Polymorphism','An abstract class has a pure virtual function without a final override and cannot be instantiated directly.','abstract کلاس میں نامکمل pure virtual عمل ہوتا ہے اور اس کا براہ راست آبجیکٹ نہیں بنتا۔','Define a required operation with =0.~ضروری عمل =0 سے لکھیں۔|A concrete derived class must implement all remaining pure virtual operations.~مکمل ڈیرائیوڈ کلاس باقی pure virtual عمل دے۔|Use a base reference to work with different concrete implementations uniformly.~بیس ریفرنس سے مختلف اصل کلاس یکساں استعمال کریں۔','Square s;\nShape& shape=s;\nstd::cout << shape.area();','', 'struct Shape{virtual int area() const=0;virtual ~Shape()=default;};\nstruct Square:Shape{int area() const override{return 4;}};')
A('Virtual destructors','ورچوئل ڈسٹرکٹر','11. Polymorphism','A virtual destructor enables correct destruction through a pointer to a polymorphic base.','ورچوئل ڈسٹرکٹر بیس پوائنٹر سے مکمل ڈیرائیوڈ صفائی ممکن کرتا ہے۔','The pointer has static type unique_ptr<Base> but owns a Child.~پوائنٹر بیس کا ہے مگر آبجیکٹ Child ہے۔|Deleting through the base requires an appropriate virtual destructor for this ownership design.~اس طرح بیس سے حذف کرنے میں virtual destructor ضروری ہے۔|The Child destructor runs before the Base destructor.~پہلے Child پھر Base کی صفائی ہوتی ہے۔','std::unique_ptr<Base> p=std::make_unique<Child>();','memory','struct Base{virtual ~Base(){std::cout<<"Base ";}};\nstruct Child:Base{~Child(){std::cout<<"Child ";}};')
A('dynamic_cast','چیک شدہ ڈائنامک کاسٹ','11. Polymorphism','dynamic_cast performs supported runtime-checked conversions in polymorphic class hierarchies.','dynamic_cast ورچوئل درجہ بندی میں runtime پر درست تبدیلی چیک کرتا ہے۔','The source base class is polymorphic because it has a virtual destructor.~ورچوئل destructor بیس کو polymorphic بناتا ہے۔|A pointer downcast returns nullptr if the actual object is not the requested derived type.~غلط اصل قسم پر پوائنٹر cast نل دیتا ہے۔|Check the result before using derived members; a failed reference cast instead throws bad_cast.~رکن سے پہلے نتیجہ چیک کریں؛ ریفرنس کی ناکامی ایکسپشن ہے۔','Child c;\nBase* b=&c;\nif (auto* p=dynamic_cast<Child*>(b)) std::cout << p->value;','', 'struct Base{virtual ~Base()=default;};\nstruct Child:Base{int value{7};};')
A('std::vector','بڑھنے والا ویکٹر','15. Standard library','vector is a dynamically sized contiguous sequence container.','vector مسلسل میموری میں بڑھنے والی ترتیب ہے۔','Construct a sequence and use zero-based indices.~فہرست بنائیں؛ پہلا انڈیکس صفر ہے۔|push_back adds an element, possibly reallocating storage.~آخر میں عنصر بڑھنے سے میموری دوبارہ بن سکتی ہے۔|Use at for checked access. size counts elements; capacity counts allocated element slots.~at حد دیکھتا، size عناصر اور capacity جگہ گنتا ہے۔','std::vector<int> v{2,4};\nv.push_back(6);\nstd::cout << v.at(2) << " " << v.size();','vector')
A('std::list','لنکڈ لسٹ کنٹینر','15. Standard library','list is a bidirectional linked sequence supporting stable node-based insertion and erasure.','list دو طرفہ جڑے نوڈز کی ترتیب ہے۔','Elements are separate nodes rather than contiguous array slots.~عناصر مسلسل خانوں کے بجائے الگ نوڈ ہیں۔|Insert or erase at a known iterator without shifting all later elements.~معلوم اٹیریٹر پر باقی عناصر کھسکائے بغیر تبدیلی ہو سکتی ہے۔|There is no indexing operator; traversal to the nth element is linear.~انڈیکس آپریٹر نہیں؛ خاص مقام تک چلنا پڑتا ہے۔','std::list<int> values{2,3};\nvalues.push_front(1);\nfor(int x:values)std::cout << x << " ";','list')
A('std::deque','دونوں سروں والا کنٹینر','15. Standard library','deque is a double-ended sequence with random-access indexing.','deque دونوں سروں سے کام اور انڈیکس رسائی دیتا ہے۔','Unlike vector, storage need not form one contiguous block.~vector کے برخلاف میموری ایک مسلسل بلاک نہیں۔|push_front and push_back add at either end.~دونوں سروں پر عنصر شامل کریں۔|Iterator invalidation rules differ from vector, so check them before keeping iterators across changes.~اٹیریٹر کے اصول vector سے مختلف ہیں؛ تبدیلی پر احتیاط کریں۔','std::deque<int> q{2};\nq.push_front(1);q.push_back(3);\nfor(int x:q)std::cout << x << " ";','deque')
A('std::set','منفرد مرتب عناصر','15. Standard library','set stores unique keys ordered by a comparison function.','set موازنے کے مطابق ترتیب میں منفرد کلیدیں رکھتا ہے۔','Insert keys without manually checking for duplicates.~نقل کی خود جانچ کے بغیر کلید شامل کریں۔|A duplicate equivalent key does not add another element.~برابر کلید دوسری کاپی نہیں بڑھاتی۔|Traversal uses key order rather than insertion order; typical key operations are logarithmic.~ترتیب کلید کی ہے، داخلے کی نہیں؛ عام کام logarithmic ہیں۔','std::set<int> s{3,1,3,2};\nfor(int x:s)std::cout << x << " ";','set')
A('std::map','کلید اور قدر','15. Standard library','map stores unique ordered keys associated with values.','map منفرد مرتب کلید کے ساتھ قدر رکھتا ہے۔','Choose a key that identifies each record.~ہر ریکارڈ کی شناخت والی کلید لیں۔|operator[] inserts a missing key with a value-initialized mapped value before returning a reference.~[] غیر موجود کلید کو شامل بھی کرتا ہے۔|Use find or at when looking up should not silently insert an entry.~خاموش اضافہ نہیں چاہیے تو find یا at لیں۔','std::map<std::string,int> marks{{"Ali",80}};\nmarks["Sara"]=90;\nstd::cout << marks.at("Sara");','map string')
A('std::unordered_map','ہیش نقشہ','Modern library','unordered_map is a hash-based associative container without sorted traversal order.','unordered_map ہیش پر مبنی نقشہ ہے، مرتب traversal نہیں دیتا۔','Keys are assigned to buckets using their hash.~ہیش کلید کو bucket سے جوڑتا ہے۔|Equality distinguishes keys even if hashes collide.~ہیش ٹکرائے تو برابری فرق دیکھتی ہے۔|Lookup is average constant time, but worst-case linear; never depend on iteration order.~اوسط تلاش مستقل، بدترین خطی ہے؛ traversal ترتیب فرض نہ کریں۔','std::unordered_map<std::string,int> count;\n++count["cpp"];++count["cpp"];\nstd::cout << count.at("cpp");','unordered_map string')
A('std::array','مقررہ سائز کا ارے','Modern library','array is a fixed-size contiguous container whose size is part of its type.','array کا مقررہ سائز اس کی ٹائپ کا حصہ ہے۔','array<int,3> always contains three ints.~اس ٹائپ میں ہمیشہ تین int ہیں۔|It supports begin, end and size like other containers.~دوسرے کنٹینر جیسے begin، end، size ہیں۔|It owns its elements and can be copied as a value; its size cannot grow.~اپنے عناصر رکھتا اور کاپی ہوتا ہے، مگر بڑھتا نہیں۔','std::array<int,3> a{2,4,6};\nstd::cout << a.size() << " " << a.at(1);','array')
A('std::stack','سٹیک','Modern library','stack is a last-in, first-out container adapter.','stack میں آخری آنے والا پہلے نکلتا ہے۔','push adds at the top.~push اوپر قدر ڈالتا ہے۔|top reads the newest element without removing it.~top تازہ قدر پڑھتا ہے، نکالتا نہیں۔|pop removes it and returns no value; check empty before top or pop.~pop قدر واپس نہیں دیتا؛ خالی ہونے کی جانچ کریں۔','std::stack<int> s;\ns.push(10);s.push(20);\nstd::cout << s.top();\ns.pop();','stack')
A('std::queue','کیو','Modern library','queue is a first-in, first-out container adapter.','queue میں پہلے آنے والا پہلے نکلتا ہے۔','push appends to the back.~push آخر میں ڈالتا ہے۔|front reads the oldest element.~front سب سے پرانا عنصر پڑھتا ہے۔|pop removes the front; check empty before accessing or removing.~pop اگلا عنصر نکالتا ہے؛ پہلے خالی ہونے کی جانچ کریں۔','std::queue<int> q;\nq.push(10);q.push(20);\nstd::cout << q.front();\nq.pop();','queue')
A('std::priority_queue','ترجیحی کیو','Modern library','priority_queue exposes the highest-priority element according to its comparison policy.','priority_queue مقررہ موازنے سے سب سے اہم عنصر دیتا ہے۔','The default policy puts the largest value at the top.~عام پالیسی سب سے بڑا عدد اوپر رکھتی ہے۔|push maintains the heap ordering internally.~push اندر heap ترتیب برقرار رکھتا ہے۔|top reads the best element and pop removes it, regardless of insertion order.~top اہم قدر اور pop اسے نکالتا ہے، داخلے کی ترتیب نہیں۔','std::priority_queue<int> q;\nq.push(3);q.push(9);q.push(1);\nstd::cout << q.top();','queue')
A('std::span','بغیر ملکیت کا ویو','Modern library','span is a non-owning view over a contiguous sequence, introduced in C++20.','span مسلسل عناصر کا بغیر ملکیت ویو ہے۔','Create storage elsewhere, such as an array or vector.~اصل ذخیرہ array یا vector میں بنائیں۔|Construct a span referring to that storage.~span اسی میموری کو دیکھتا ہے۔|Keep the storage alive and stable; destroying or reallocating it can invalidate the span.~اصل میموری زندہ اور مستحکم رکھیں؛ تبدیلی span خراب کر سکتی ہے۔','int a[]{1,2,3};\nstd::span<int> s{a};\ns[1]=8;\nstd::cout << a[1];','span')
A('std::pair','دو قدروں کا جوڑا','Modern library','pair groups two potentially different values into one object.','pair دو ممکنہ مختلف ٹائپ کی قدریں ایک آبجیکٹ میں رکھتا ہے۔','Declare the first and second types.~پہلی اور دوسری ٹائپ بتائیں۔|Access members as first and second, or unpack with structured bindings.~first، second یا structured binding سے پڑھیں۔|Copying the pair copies its members according to their own semantics.~pair کی کاپی ارکان کے اپنے اصول کے مطابق ہوتی ہے۔','std::pair<std::string,int> student{"Ali",85};\nstd::cout << student.first << " " << student.second;','utility string')
A('std::tuple','کئی قدروں کا گروپ','Modern library','tuple stores a fixed number of values whose types may differ.','tuple مقررہ تعداد کی مختلف ٹائپس رکھ سکتا ہے۔','Specify a type for each position.~ہر مقام کی ٹائپ دیں۔|Use std::get with a compile-time index to select one element.~مستقل انڈیکس سے get عنصر چنتا ہے۔|Use a named struct when field names would explain the data better than numeric positions.~عددی جگہ سے زیادہ نام واضح ہوں تو struct بہتر ہے۔','std::tuple<std::string,int,bool> student{"Sara",90,true};\nstd::cout << std::get<0>(student) << " " << std::get<1>(student);','tuple string')
A('std::optional','ممکنہ قدر','Modern library','optional models a value that may be absent.','optional قدر کے موجود یا غیر موجود ہونے کو ظاہر کرتا ہے۔','A default optional contains no value.~ابتدا میں کوئی قدر نہیں۔|Check its Boolean state or has_value before dereferencing.~پڑھنے سے پہلے حالت چیک کریں۔|Use value_or for a fallback instead of inventing a magic sentinel value.~خاص جادوئی عدد کے بجائے value_or سے متبادل لیں۔','std::optional<int> age;\nstd::cout << age.value_or(-1) << " ";\nage=20;\nif(age)std::cout << *age;','optional')
A('std::variant','متبادل ٹائپس','Modern library','variant holds one active alternative from a fixed set of types.','variant طے شدہ ٹائپس میں سے ایک فعال قدر رکھتا ہے۔','List the allowed alternatives in the template arguments.~قابلِ قبول ٹائپس کی فہرست دیں۔|Assigning a different alternative changes the active type.~دوسری ٹائپ دینے سے فعال قسم بدلتی ہے۔|visit applies an operation to the active value; the visitor must handle every alternative.~visit فعال قدر چلاتا ہے؛ ہر ممکن ٹائپ سنبھالیں۔','std::variant<int,std::string> value=7;\nvalue=std::string{"hello"};\nstd::visit([](const auto& x){std::cout << x;},value);','variant string')
A('std::any','چھپی ہوئی ٹائپ کی قدر','Modern library','any stores a value of a copy-constructible type with runtime type information.','any قابلِ کاپی ٹائپ کی قدر runtime معلومات کے ساتھ رکھتا ہے۔','Store a value without listing all possible alternatives beforehand.~پہلے تمام ٹائپس بتائے بغیر قدر رکھیں۔|Recover the exact type with any_cast.~اصل درست ٹائپ any_cast سے لیں۔|The pointer form returns nullptr on a mismatch; the value form can throw bad_any_cast.~پوائنٹر صورت غلط ٹائپ پر nullptr، ویلیو صورت ایکسپشن دے سکتی ہے۔','std::any value=42;\nif(auto* p=std::any_cast<int>(&value))std::cout << *p;','any')
A('std::string_view','بغیر ملکیت متن','Modern library','string_view is a non-owning view of a character sequence.','string_view متن کا مالک بنے بغیر اسے دیکھتا ہے۔','Point the view at text with a sufficient lifetime.~ویو ایسے متن پر دیں جو کافی دیر زندہ رہے۔|Operations such as substr create another view rather than copying the characters.~substr اکثر نیا ویو ہے، متن کی کاپی نہیں۔|Do not return a view of a local string that is about to die; a view is not necessarily null-terminated.~ختم مقامی string کا ویو نہ دیں؛ آخر میں null ہونا بھی ضروری نہیں۔','std::string_view word="learning";\nstd::cout << word.substr(0,5);','string_view')
A('std::unique_ptr','ایک مالک والا پوائنٹر','Memory & safety','unique_ptr owns one managed object exclusively and destroys it automatically.','unique_ptr ایک آبجیکٹ کی واحد ملکیت اور خودکار صفائی دیتا ہے۔','Create ownership with make_unique.~make_unique سے مالک بنائیں۔|Dereference only while the owner is non-null.~صرف غیر نل مالک کی قدر پڑھیں۔|Move transfers ownership and leaves the moved-from unique_ptr empty; copying is disabled.~موو ملکیت منتقل اور پرانا unique_ptr خالی کرتا ہے؛ کاپی منع ہے۔','auto first=std::make_unique<int>(42);\nauto second=std::move(first);\nstd::cout << *second << " " << (first==nullptr);','memory utility')
A('std::shared_ptr','مشترک ملکیت','Memory & safety','shared_ptr keeps an object alive while at least one strong owner remains.','shared_ptr کم از کم ایک مضبوط مالک تک آبجیکٹ زندہ رکھتا ہے۔','make_shared creates an object with shared ownership bookkeeping.~make_shared آبجیکٹ اور مشترک ملکیت بناتا ہے۔|Copying the pointer adds an owner of the same object, not an object copy.~پوائنٹر کاپی مالک بڑھاتی ہے، آبجیکٹ نہیں۔|The last owner destroys the object. Shared ownership does not make the object itself thread-safe.~آخری مالک صفائی کرتا ہے؛ آبجیکٹ خود thread-safe نہیں بن جاتا۔','auto a=std::make_shared<int>(7);\nauto b=a;\n*b=9;\nstd::cout << *a;','memory')
A('std::weak_ptr','کمزور مشاہدہ پوائنٹر','Memory & safety','weak_ptr observes shared ownership without keeping the object alive.','weak_ptr مشترک آبجیکٹ دیکھتا ہے مگر اسے زندہ رکھنے کی ملکیت نہیں بڑھاتا۔','Create it from a shared_ptr.~shared_ptr سے بنائیں۔|lock attempts to obtain a temporary strong owner.~lock عارضی مضبوط مالک لینے کی کوشش کرتا ہے۔|Check the returned shared_ptr; it is empty if the object has already expired.~اگر آبجیکٹ ختم ہو چکا تو نتیجہ خالی ہے؛ چیک کریں۔','auto owner=std::make_shared<int>(7);\nstd::weak_ptr<int> view=owner;\nif(auto p=view.lock())std::cout << *p;','memory')
A('std::sort','عناصر ترتیب دینا','15. Standard library','sort rearranges a random-access range according to a strict weak ordering.','sort مناسب موازنے کے مطابق رینج کو ترتیب دیتا ہے۔','Pass begin and end to identify the half-open range.~begin شامل اور end خارج حد دیں۔|The default order is ascending for ordinary integers.~عام اعداد چھوٹے سے بڑے ہوتے ہیں۔|A custom comparator must be consistent; using <= instead of < is not a valid strict comparison.~اپنا comparator مسلسل اور strict ہو؛ <= کو < کی جگہ نہ دیں۔','std::vector<int> v{4,1,3};\nstd::sort(v.begin(),v.end());\nfor(int x:v)std::cout << x << " ";','vector algorithm')
A('std::find','قدر تلاش کرنا','15. Standard library','find performs a linear search and returns the first matching iterator or the end iterator.','find خطی تلاش سے پہلی برابر جگہ یا end دیتا ہے۔','Choose the range and the value to match.~رینج اور مطلوبہ قدر منتخب کریں۔|Compare the returned iterator against end before dereferencing.~پڑھنے سے پہلے end سے موازنہ کریں۔|If no match exists, end is only a boundary and must not be read as an element.~نہ ملے تو end عنصر نہیں، اس کی قدر نہ پڑھیں۔','std::vector<int> v{2,4,6};\nauto it=std::find(v.begin(),v.end(),4);\nif(it!=v.end())std::cout << *it;','vector algorithm')
A('std::accumulate','ترتیب کا مجموعہ','Modern library','accumulate combines a range into an accumulator using a binary operation.','accumulate رینج کی قدریں ایک جمع ہونے والے نتیجے میں ملاتا ہے۔','Supply an initial accumulator value.~ابتدائی نتیجہ دیں۔|Its type determines the accumulator type: 0 uses int and 0.0 uses double.~0 سے int اور 0.0 سے double حساب بنتا ہے۔|Each element updates the accumulator in order; choose a type large enough for the result.~ہر عنصر ترتیب سے شامل ہوتا ہے؛ مناسب حد والی ٹائپ لیں۔','std::vector<int> v{1,2,3};\nstd::cout << std::accumulate(v.begin(),v.end(),0);','vector numeric')
A('std::transform','ہر عنصر تبدیل کرنا','15. Standard library','transform applies an operation to input elements and writes the results to an output range.','transform ہر ان پٹ پر عمل کر کے نتیجہ آؤٹ پٹ رینج میں لکھتا ہے۔','Allocate enough output elements or use an insertion iterator.~کافی آؤٹ پٹ جگہ یا insertion iterator دیں۔|Supply a callable that transforms one element.~ایک عنصر بدلنے والا callable دیں۔|Do not write beyond the output range; output.begin alone does not grow an empty vector.~خالی vector کا begin خود جگہ نہیں بڑھاتا؛ حد نہ پار کریں۔','std::vector<int> in{1,2,3},out(3);\nstd::transform(in.begin(),in.end(),out.begin(),[](int x){return x*2;});\nfor(int x:out)std::cout << x << " ";','vector algorithm')
A('std::all_of','سب عناصر کی شرط','Modern library','all_of reports whether every element in a range satisfies a predicate.','all_of دیکھتا ہے کہ ہر عنصر شرط پوری کرتا ہے یا نہیں۔','Write a Boolean predicate for one element.~ایک عنصر کی Boolean شرط لکھیں۔|The algorithm stops when it finds a false predicate result.~غلط نتیجہ ملے تو رک سکتا ہے۔|For an empty range all_of returns true; any_of would return false.~خالی رینج پر all_of درست جبکہ any_of غلط ہے۔','std::vector<int> v{2,4,6};\nstd::cout << std::all_of(v.begin(),v.end(),[](int n){return n%2==0;});','vector algorithm')
A('std::chrono durations','وقت کا دورانیہ','Modern library','A chrono duration represents a count of time ticks with a compile-time period.','chrono duration وقت کے ٹِک اور ان کی اکائی رکھتا ہے۔','Use named units such as seconds or milliseconds.~seconds یا milliseconds جیسی اکائی لیں۔|duration_cast converts counts between periods, with truncation when converting to a coarser integral unit.~موٹی integral اکائی میں چھوٹا حصہ کٹ سکتا ہے۔|Keep units attached to values instead of mixing unnamed raw integers.~بے نام اعداد کے بجائے اکائی ساتھ رکھیں۔','std::chrono::seconds s{2};\nauto ms=std::chrono::duration_cast<std::chrono::milliseconds>(s);\nstd::cout << ms.count();','chrono')
A('std::regex','متن کے پیٹرن','Modern library','regex represents a regular-expression pattern used to match or search text.','regex متن کا پیٹرن ہے جس سے تلاش یا موازنہ ہوتا ہے۔','Write the pattern using the selected regex grammar.~منتخب grammar کے مطابق پیٹرن لکھیں۔|regex_match requires the entire string to match, while regex_search looks for a matching portion.~match پوری string اور search کسی حصے کو دیکھتا ہے۔|For simple exact text checks, ordinary string operations may be clearer and cheaper.~سادہ متن کے لیے string کا عمل آسان اور ہلکا ہو سکتا ہے۔','std::regex digits("[0-9]+");\nstd::string s="123";\nstd::cout << std::regex_match(s,digits);','regex string')
A('std::filesystem paths','فائل کے راستے','Modern library','filesystem::path represents a path in the native filesystem syntax.','filesystem::path فائل سسٹم کے راستے کی نمائندگی ہے۔','Build a path from components instead of manually guessing separators.~حصے جوڑیں، slash خود اندازے سے نہ بنائیں۔|filename and extension inspect the path text without requiring the file to exist.~filename اور extension متن دیکھتے ہیں؛ فائل موجود ہونا ضروری نہیں۔|Actual filesystem operations can fail through permission or race conditions and need error handling.~اصل کام اجازت یا race سے ناکام ہو سکتا ہے؛ خرابی سنبھالیں۔','std::filesystem::path p="notes/intro.cpp";\nstd::cout << p.filename().string() << " " << p.extension().string();','filesystem')
A('std::expected','نتیجہ یا خرابی','Modern library','expected<T,E> contains either a success value T or an error E, introduced in C++23.','expected میں کامیابی کی T قدر یا E خرابی ہوتی ہے۔','Use a value for success and unexpected for failure.~کامیابی پر قدر، ناکامی پر unexpected دیں۔|Test the state before accessing the contained result.~نتیجہ پڑھنے سے پہلے حالت چیک کریں۔|Unlike optional, expected carries an explanation of failure through its error type.~optional کے برخلاف خرابی کی معلومات بھی ہوتی ہیں۔','std::expected<int,std::string> result=std::unexpected("Not found");\nif(result)std::cout << *result;\nelse std::cout << result.error();','expected string')
A('try, catch and throw','ایکسپشن کے تین حصے','14. Templates & exceptions','throw reports an exception; try and catch establish a handler for matching failures.','throw ایکسپشن دیتا، try اور catch مناسب خرابی سنبھالتے ہیں۔','Place potentially failing work inside try.~ممکنہ ناکامی try میں رکھیں۔|Throw a meaningful exception type when the operation cannot fulfill its contract.~مقصد پورا نہ ہو تو مناسب قسم کی ایکسپشن دیں۔|Catch by const reference and either recover or report; do not silently hide all failures.~const ریفرنس سے پکڑیں، حل یا رپورٹ کریں، خاموش نہ چھپائیں۔','try { throw std::invalid_argument("Age cannot be negative"); }\ncatch(const std::exception& e){std::cout << e.what();}','stdexcept')
A('std::thread and join','تھریڈ اور انتظار','Concurrency','thread starts an execution thread; join waits for that thread to finish.','thread الگ عمل شروع اور join مکمل ہونے کا انتظار کرتا ہے۔','Construct the thread with a callable whose captured data outlives its use.~callable کا ڈیٹا استعمال تک زندہ رکھیں۔|The caller can do other work before joining.~caller انتظار سے پہلے دوسرا کام کر سکتا ہے۔|A joinable thread must be joined or detached before destruction, otherwise terminate is called.~ختم ہونے سے پہلے join یا detach لازم ہے، ورنہ terminate ہوتا ہے۔','std::thread worker([]{std::cout << "Worker finished";});\nworker.join();','thread')
A('std::mutex','مشترک رسائی کا تالہ','Concurrency','mutex provides exclusive ownership for synchronizing a critical section.','mutex اہم مشترک حصے میں ایک وقت میں ایک مالک دیتا ہے۔','Identify all accesses that can conflict on shared state.~مشترک ڈیٹا کی ٹکرانے والی رسائی پہچانیں۔|Guard them with the same mutex and an RAII lock.~سب کو ایک ہی mutex اور RAII لاک سے محفوظ کریں۔|A mutex protects only code that obeys the locking discipline; it does not automatically protect every related variable.~صرف لاک کے اصول ماننے والا کوڈ محفوظ ہے، ہر متغیر خود نہیں۔','std::mutex m;\nint value{};\n{std::lock_guard lock(m);value=5;}\nstd::cout << value;','mutex')
A('Condition variables','شرط کے انتظار کا ذریعہ','Concurrency','A condition variable lets a thread wait efficiently for a shared-state predicate to become true.','condition variable مشترک شرط درست ہونے کا مؤثر انتظار ہے۔','Keep the predicate state under a mutex.~شرط والا ڈیٹا mutex میں رکھیں۔|wait releases the lock while waiting and reacquires it before checking the predicate again.~wait انتظار میں لاک چھوڑتا پھر شرط سے پہلے دوبارہ لیتا ہے۔|Always use a predicate loop or overload because wakeups may be spurious and notifications are not stored events.~دوبارہ شرط لازمی دیکھیں؛ ہر بیداری حقیقی تبدیلی نہیں۔','std::mutex m;\nstd::condition_variable cv;\nbool ready=false;\nstd::thread worker([&]{{std::lock_guard lock(m);ready=true;}cv.notify_one();});\n{std::unique_lock lock(m);cv.wait(lock,[&]{return ready;});}\nworker.join();\nstd::cout << "Ready";','thread mutex condition_variable')
A('std::atomic','ایٹامک متغیر','Concurrency','atomic<T> provides indivisible operations and memory-ordering control for supported types.','atomic مخصوص ٹائپ پر ناقابلِ تقسیم عمل اور میموری ترتیب دیتا ہے۔','Use an atomic counter when individual increments must not race.~اضافے میں race روکنے کے لیے atomic count لیں۔|fetch_add returns the old value and atomically adds to the stored value.~fetch_add پرانی قدر دیتا اور اضافہ کرتا ہے۔|Several separate atomic operations do not automatically form one indivisible transaction.~کئی الگ atomic عمل ایک مکمل transaction نہیں بنتے۔','std::atomic<int> count{5};\nint before=count.fetch_add(2);\nstd::cout << before << " " << count.load();','atomic')
A('Futures and promises','فیوچر اور پرامس','Concurrency','A promise supplies a result to shared state; its future retrieves that result.','promise نتیجہ مشترک حالت میں دیتا اور future اسے لیتا ہے۔','Obtain the future from the promise before consuming the result.~نتیجہ لینے سے پہلے future حاصل کریں۔|set_value makes the shared result ready.~set_value نتیجہ تیار کرتا ہے۔|get waits if necessary and retrieves the result; an ordinary future is consumed by get.~get ضرورت پر انتظار کرتا اور عام future کا نتیجہ ایک بار لیتا ہے۔','std::promise<int> p;\nauto f=p.get_future();\np.set_value(42);\nstd::cout << f.get();','future')
A('Type aliases with using','ٹائپ کا دوسرا نام','13. Program organization','A using alias gives an existing type another name without creating a distinct type.','using موجودہ ٹائپ کا دوسرا نام دیتا ہے، نئی الگ ٹائپ نہیں۔','Choose a name that explains a type’s role.~نام سے ٹائپ کا مقصد واضح کریں۔|Use that alias wherever the underlying type is expected.~اصل ٹائپ کی جگہ alias لیں۔|Aliases do not add validation or prevent mixing values that share the same underlying type.~alias نئی جانچ یا الگ محفوظ ٹائپ نہیں بناتا۔','using Score=int;\nScore marks{90};\nstd::cout << marks;')
A('static_cast','واضح سٹیٹک تبدیلی','2. Foundations','static_cast requests supported explicit compile-time conversions between related types.','static_cast متعلقہ ٹائپس کے درمیان واضح تبدیلی مانگتا ہے۔','Use it to make a deliberate numeric conversion visible.~جان بوجھ کر عددی تبدیلی واضح کریں۔|Converting a floating-point value to int discards its fractional part when the result is representable.~حد کے اندر double سے int میں اعشاری حصہ کٹتا ہے۔|It is not a runtime downcast check; do not use it to guess an object’s actual derived type.~یہ runtime downcast چیک نہیں؛ اصل قسم کا اندازہ نہ لگائیں۔','double value{3.9};\nint whole=static_cast<int>(value);\nstd::cout << whole;')
A('Pointers versus references','پوائنٹر اور ریفرنس کا فرق','10. Pointers','A pointer is an address-valued object; a reference is an alias bound to another object.','پوائنٹر پتہ رکھنے والا آبجیکٹ جبکہ ریفرنس دوسرے آبجیکٹ کا نام ہے۔','A pointer can be null or reassigned to a different object.~پوائنٹر نل یا کسی دوسرے آبجیکٹ پر جا سکتا ہے۔|A reference is initialized to its referent and cannot be reseated using assignment.~ریفرنس ابتدا میں جڑتا ہے؛ assignment سے نئی جگہ نہیں جڑتا۔|Assigning through a reference changes the referred-to object instead of changing the binding.~ریفرنس میں assignment اصل قدر بدلتی ہے، تعلق نہیں۔','int a{1},b{2};\nint& r=a;\nint* p=&a;\np=&b;r=9;\nstd::cout << a << " " << *p;')
A('Pointer arithmetic','پوائنٹر کا حساب','10. Pointers','Pointer arithmetic moves between elements within an array and its one-past boundary.','پوائنٹر حساب ایک ارے کے عناصر اور آخری کے بعد حد تک جاتا ہے۔','Adding one advances by one element, not by one raw byte.~ایک جمع کرنے سے ایک عنصر آگے جاتے ہیں، صرف بائٹ نہیں۔|The result must stay within the same array or its one-past position.~اسی ارے یا اس کی آخری کے بعد حد میں رہیں۔|A one-past pointer may be compared but must not be dereferenced.~آخری کے بعد والے پوائنٹر کی قدر نہ پڑھیں۔','int a[]{10,20,30};\nint* p=a;\nstd::cout << *(p+1);')
A('Function pointers','فنکشن کا پوائنٹر','10. Pointers','A function pointer stores the address of a function with a compatible signature.','فنکشن پوائنٹر مناسب signature والے فنکشن کا پتہ رکھتا ہے۔','Match return and parameter types in the pointer declaration.~return اور پیرامیٹر ٹائپس ملائیں۔|Assign the address of a compatible function.~اسی signature کا پتہ دیں۔|Calling through the pointer invokes the selected function; ensure the pointer is non-null.~پوائنٹر سے منتخب فنکشن چلتا ہے؛ نل نہ ہو۔','int (*operation)(int)=&twice;\nstd::cout << operation(6);','', 'int twice(int x){return x*2;}')
A('Multidimensional arrays','کئی جہتی ارے','7. Arrays & strings','A built-in multidimensional array is an array whose elements are themselves arrays.','کئی جہتی ارے میں ہر عنصر خود ایک ارے ہے۔','int grid[2][3] has two rows and three columns per row.~دو قطار اور ہر قطار میں تین خانے ہیں۔|Use one index per dimension, both starting at zero.~ہر جہت کا انڈیکس صفر سے شروع کریں۔|grid[1][2] selects the second row and third column; each index must meet its own bound.~یہ دوسری قطار کا تیسرا خانہ ہے؛ دونوں حدیں درست ہوں۔','int grid[2][3]{{1,2,3},{4,5,6}};\nstd::cout << grid[1][2];')
A('C-style strings','سی طرز کی سٹرنگ','7. Arrays & strings','A C string is a character sequence terminated by a null character.','C سٹرنگ کے آخر میں null حرف ہوتا ہے۔','The array must have room for characters and the trailing zero.~حروف کے ساتھ آخری صفر کی جگہ رکھیں۔|The string literal initializes Hi plus its terminating null, requiring three elements.~Hi کے ساتھ null مل کر تین عناصر بنتے ہیں۔|strlen counts characters before the null, not the array’s total capacity.~strlen null سے پہلے گنتا ہے، پوری گنجائش نہیں۔','char text[]{"Hi"};\nstd::cout << std::strlen(text) << " " << sizeof(text);','cstring')
A('Friend functions','فرینڈ فنکشن','11. Polymorphism','A friend declaration grants a function or class access to otherwise restricted members.','friend کسی فنکشن یا کلاس کو نجی ارکان کی اجازت دیتا ہے۔','Declare the friendship inside the class granting access.~اجازت دینے والی کلاس کے اندر friend لکھیں۔|The friend function remains a non-member and has no implicit this pointer.~friend فنکشن رکن نہیں اور خودکار this نہیں رکھتا۔|Grant only needed access; friendship is neither inherited nor transitive.~صرف ضروری اجازت دیں؛ دوستی خود وراثت یا سلسلے میں نہیں بڑھتی۔','Box b;\nstd::cout << reveal(b);','', 'class Box{int value{7};friend int reveal(const Box&);};\nint reveal(const Box& b){return b.value;}')
A('Copy assignment','موجودہ آبجیکٹ میں کاپی','11. Polymorphism','Copy assignment replaces the state of an already existing object using another object.','کاپی assignment پہلے سے موجود آبجیکٹ کی حالت دوسرے سے بدلتی ہے۔','Construct both source and destination first.~دونوں آبجیکٹ پہلے بنے ہوں۔|b=a calls assignment rather than constructing b anew.~b=a نیا b نہیں بناتا، حالت بدلتا ہے۔|Standard owning members manage replacement safely; manually owned resources need correct self-assignment and cleanup behavior.~معیاری ارکان صفائی کرتے ہیں؛ دستی وسائل میں self-assignment کا خیال رکھیں۔','std::string a="first",b="second";\nb=a;\nstd::cout << b;','string')
A('explicit constructors','واضح کنسٹرکٹر','8. Operator overloading','explicit prevents a constructor or conversion operator from participating in selected implicit conversions.','explicit بعض خودکار تبدیلیاں روک کر واضح ارادہ مانگتا ہے۔','A one-argument constructor can otherwise create surprising conversions.~ایک پیرامیٹر والا کنسٹرکٹر غیر متوقع تبدیلی کر سکتا ہے۔|Mark it explicit when the caller should name the conversion.~تبدیلی واضح چاہیے تو explicit لگائیں۔|Direct construction such as Meter m{3} remains valid.~براہ راست Meter m{3} اب بھی درست ہے۔','Meter m{3};\nstd::cout << m.value;','', 'struct Meter{int value;explicit Meter(int n):value(n){}};')
A('mutable members','کانسٹ کے اندر بدلنے والا رکن','8. Operator overloading','mutable permits a member to change even through a const-qualified object.','mutable رکن const آبجیکٹ کے ذریعے بھی بدل سکتا ہے۔','Use it for internal bookkeeping that does not change the logical value.~منطقی قدر کے بجائے اندرونی حساب کے لیے استعمال کریں۔|A const method may update a mutable counter.~const فنکشن mutable شمار بدل سکتا ہے۔|mutable does not supply synchronization; concurrent changes still need protection.~mutable تھریڈ حفاظت نہیں دیتا؛ مشترک تبدیلی محفوظ کریں۔','const Reading r;\nr.get();r.get();\nstd::cout << r.reads;','', 'struct Reading{mutable int reads{};int get() const{++reads;return 7;}};')
A('static local variables','مقامی سٹیٹک متغیر','5. Functions','A static local has block scope but storage lasting for the program’s lifetime.','مقامی static کا نام بلاک میں مگر ذخیرہ پروگرام بھر رہتا ہے۔','Initialization occurs when control first reaches the declaration.~اعلان تک پہلی آمد پر ابتدا ہوتی ہے۔|Later calls reuse the same object rather than making a fresh one.~بعد کی کال وہی آبجیکٹ استعمال کرتی ہے۔|Initialization is thread-safe since C++11, but subsequent modifications are not automatically synchronized.~ابتدائی بننا محفوظ ہے، بعد کی تبدیلی خود محفوظ نہیں۔','std::cout << next() << " " << next();','', 'int next(){static int n=0;return ++n;}')
A('Command-line arguments','کمانڈ لائن آرگومنٹ','12. Streams & files','argc and argv provide a program’s argument count and argument strings at startup.','argc اور argv آغاز پر آرگومنٹ کی تعداد اور متن دیتے ہیں۔','argc counts available argument entries; argv holds their C-string pointers.~argc تعداد اور argv متن کے پوائنٹر ہیں۔|Check the count before reading a particular argument.~کسی خاص آرگومنٹ سے پہلے تعداد دیکھیں۔|Numeric arguments arrive as text and require validated parsing.~عددی آرگومنٹ بھی متن ہیں؛ جانچ کر تبدیل کریں۔','std::cout << "Local form: int main(int argc, char* argv[])";')
A('Include guards','ہیڈر کی تکرار روکنا','13. Program organization','An include guard prevents repeated processing of a header in one translation unit.','include guard ایک translation unit میں ہیڈر کی تکرار روکتا ہے۔','Use a unique macro name around the header contents.~ہیڈر کے گرد منفرد macro نام لیں۔|The first inclusion defines the macro and includes the declarations.~پہلی بار macro اور اعلانات آتے ہیں۔|Later inclusions skip the contents; this does not fix conflicting definitions in different source files.~بعد میں مواد چھوڑتا ہے؛ الگ فائلوں کا ODR مسئلہ خود حل نہیں ہوتا۔','std::cout << "Header guard loaded";','', '#ifndef SAFAR_EXAMPLE_HEADER_H\n#define SAFAR_EXAMPLE_HEADER_H\nstruct HeaderExample {};\n#endif')
A('Forward declarations','پیشگی اعلان','13. Program organization','A forward declaration introduces a type name without defining its full layout.','پیشگی اعلان مکمل ساخت کے بغیر ٹائپ کا نام بتاتا ہے۔','A pointer or reference declaration can often use an incomplete class type.~پوائنٹر یا ریفرنس اکثر نامکمل کلاس سے بن سکتے ہیں۔|Creating an object by value requires its full definition and size.~اصل قدر کا آبجیکٹ بنانے کے لیے مکمل سائز چاہیے۔|Place the complete definition before operations requiring member access or destruction semantics.~ارکان یا ضروری صفائی سے پہلے مکمل تعریف دیں۔','Item item{8};\nItem* p=&item;\nstd::cout << p->value;','', 'struct Item;\nstruct Holder{Item* p;};\nstruct Item{int value;};')
A('Class templates','کلاس ٹیمپلیٹ','14. Templates & exceptions','A class template describes a family of class types parameterized by template arguments.','کلاس ٹیمپلیٹ آرگومنٹ کے مطابق کئی کلاس ٹائپس بناتا ہے۔','Use T as a placeholder in member declarations.~ارکان میں T کو ٹائپ کی جگہ لیں۔|Box<int> and Box<double> are distinct instantiated types.~int اور double کی Box الگ ٹائپس ہیں۔|Operations on T must be valid for each chosen instantiation.~ہر منتخب T کے لیے عمل درست ہونا چاہیے۔','Box<int> a{7};\nBox<double> b{2.5};\nstd::cout << a.value << " " << b.value;','', 'template<class T>struct Box{T value;};')
A('Template specialization','ٹیمپلیٹ کی خاص صورت','Modern language','Specialization supplies a specific implementation for selected template arguments.','specialization مخصوص ٹیمپلیٹ آرگومنٹ کے لیے خاص عمل دیتی ہے۔','Write the general template for common behavior.~عام عمل کے لیے بنیادی ٹیمپلیٹ لکھیں۔|Provide a specialization for the exact type that needs a different representation or operation.~ضروری خاص ٹائپ کے لیے الگ تعریف دیں۔|The specialized definition is selected for that type; function templates cannot be partially specialized.~خاص ٹائپ پر خاص تعریف آتی ہے؛ فنکشن کی partial specialization نہیں ہوتی۔','std::cout << Label<int>::name() << " " << Label<bool>::name();','', 'template<class T>struct Label{static const char* name(){return "general";}};\ntemplate<>struct Label<bool>{static const char* name(){return "bool";}};')
A('static_assert','کمپائل وقت کی شرط','Modern language','static_assert checks a constant expression and rejects compilation when it is false.','static_assert مستقل شرط غلط ہونے پر کمپائل روک دیتا ہے۔','Choose a condition known at compile time.~کمپائل وقت معلوم شرط لیں۔|Provide a message explaining the required invariant.~ضروری اصول کا پیغام لکھیں۔|Unlike runtime assert, this check does not run inside the executable and is not disabled by NDEBUG.~یہ runtime پر نہیں چلتا اور NDEBUG سے بند نہیں ہوتا۔','constexpr int capacity=10;\nstatic_assert(capacity>0,"Capacity must be positive");\nstd::cout << capacity;')
A('consteval functions','لازمی کمپائل وقت کا فنکشن','Modern language','consteval declares an immediate function whose potentially evaluated calls must produce constant expressions.','consteval فنکشن کی متعلقہ کال کا مستقل نتیجہ لازمی کرتا ہے۔','Mark a function consteval when runtime evaluation should not be allowed.~runtime حساب منع کرنا ہو تو consteval دیں۔|Pass arguments suitable for constant evaluation.~مستقل حساب کے قابل آرگومنٹ دیں۔|An ordinary runtime input cannot be passed where an immediate constant result is required.~عام runtime ان پٹ وہاں نہیں دے سکتے۔','constexpr int result=square(4);\nstd::cout << result;','', 'consteval int square(int n){return n*n;}')
A('Structured bindings','حصوں کو الگ نام دینا','Modern language','Structured bindings introduce names for the elements of a suitable aggregate, tuple-like object or array.','structured binding جوڑے، ارے یا مناسب آبجیکٹ کے حصوں کو نام دیتی ہے۔','Match the number of binding names to the decomposed elements.~ناموں کی تعداد حصوں سے ملائیں۔|auto copies into the binding object, while auto& refers to the original.~auto کاپی اور auto& اصل سے جڑتا ہے۔|Changing a reference binding updates the corresponding original member.~ریفرنس نام بدلنے سے اصل رکن بدلتا ہے۔','std::pair<int,int> point{2,3};\nauto& [x,y]=point;\nx=8;\nstd::cout << point.first;','utility')
A('Lambda captures by reference','لیمبڈا میں اصل متغیر','Modern language','A reference capture lets a lambda access the original surrounding object.','ریفرنس capture لیمبڈا کو اصل باہر والا آبجیکٹ دیتا ہے۔','Name the required captured variable explicitly with &.~ضروری متغیر کو & کے ساتھ نام دیں۔|Changing it inside the lambda changes the original object.~اندر تبدیلی اصل قدر بدلتی ہے۔|Never let the lambda use a reference after the captured object has died.~اصل آبجیکٹ ختم ہو تو لیمبڈا سے ریفرنس استعمال نہ کریں۔','int count=0;\nauto increment=[&count]{++count;};\nincrement();\nstd::cout << count;')
A('std::move','موو کا اظہار','Modern language','std::move casts an expression to an rvalue form so a move-capable operation may consume it.','std::move ایکسپریشن کو موو کے قابل شکل دیتا ہے۔','The cast does not transfer data by itself.~cast خود ڈیٹا منتقل نہیں کرتا۔|The receiving constructor or assignment decides whether and how to move.~لینے والا کنسٹرکٹر یا assignment اصل عمل کرتا ہے۔|Moving from const often selects copying instead; avoid relying on moved-from contents unless specified.~const سے اکثر کاپی بنتی ہے؛ موو کے بعد خاص قدر فرض نہ کریں۔','std::string source="hello";\nstd::string target=std::move(source);\nstd::cout << target;','string utility')
A('Iterator invalidation','اٹیریٹر کب غلط ہوتا ہے','15. Standard library','Iterator invalidation means a previously obtained iterator no longer validly refers to its old position.','invalidation میں پرانا اٹیریٹر اپنی جگہ کے لیے درست نہیں رہتا۔','Obtain iterators only when needed.~اٹیریٹر ضرورت کے وقت لیں۔|Structural changes such as vector reallocation can invalidate pointers, references and iterators.~vector کی نئی allocation پر پرانے حوالے غلط ہو سکتے ہیں۔|After a potentially invalidating change, acquire a fresh iterator instead of using the old one.~ایسی تبدیلی کے بعد نیا اٹیریٹر لیں۔','std::vector<int> v{1,2};\nv.push_back(3);\nauto fresh=v.begin();\nstd::cout << *fresh;','vector')
A('Binary search & sorted data','ترتیب والی تلاش','Design & tools','Binary search repeatedly narrows an ordered search interval using a middle comparison.','بائنری تلاش مرتب حصے کو درمیانی موازنے سے کم کرتی ہے۔','Sort using the same comparison relation used for the search.~تلاش کے موازنے کے مطابق پہلے ترتیب دیں۔|Each comparison discards a region that cannot contain the answer.~ہر موازنہ ناممکن حصہ ہٹاتا ہے۔|On random-access data the search takes logarithmic comparisons; unsorted input violates the precondition.~random-access میں موازنے logarithmic ہیں؛ غیر مرتب ڈیٹا غلط شرط ہے۔','std::vector<int> v{1,3,5,7};\nstd::cout << std::binary_search(v.begin(),v.end(),5);','vector algorithm')
A('Bitwise operators','بٹس کے آپریٹر','2. Foundations','Bitwise operators combine or shift the individual bits of integral values.','bitwise آپریٹر عدد کے الگ بٹس ملاتے یا کھسکاتے ہیں۔','Use unsigned values for straightforward flag manipulation.~سادہ flag کام کے لیے unsigned لیں۔|& intersects set bits, while | combines them and ^ toggles differences.~& مشترک، | ملے اور ^ مختلف بٹس دیتا ہے۔|Shift counts must be nonnegative and smaller than the promoted type width.~شفٹ کی گنتی صفر یا زیادہ اور ٹائپ کی چوڑائی سے کم ہو۔','unsigned flags=0;\nflags |= (1u<<2);\nstd::cout << flags << " " << ((flags & (1u<<2))!=0);')
A('std::numeric_limits','اعداد کی حدیں','2. Foundations','numeric_limits exposes implementation properties and bounds of arithmetic types.','numeric_limits عددی ٹائپس کی حدیں اور خصوصیات بتاتا ہے۔','Ask the type for its bounds instead of assuming every platform has the same width.~ہر پلیٹ فارم کا ایک سائز فرض نہ کریں۔|max gives the greatest finite value; lowest gives the most negative finite value for signed types.~max سب سے بڑی اور lowest کم ترین قدر دیتا ہے۔|For floating-point types min is the smallest positive normalized value, not the most negative value.~floating-point کا min سب سے منفی نہیں، چھوٹی مثبت normalized قدر ہے۔','std::cout << std::numeric_limits<int>::lowest() << " " << std::numeric_limits<int>::max();','limits')
A('Range views: transform','رینج کا تبدیلی ویو','Modern language','views::transform lazily applies a callable as elements are accessed.','transform ویو عنصر پڑھتے وقت تبدیلی کرتا ہے۔','Keep the underlying sequence alive.~اصل ترتیب زندہ رکھیں۔|Create a view pipeline without allocating a new result vector.~نیا vector بنائے بغیر ویو بنائیں۔|Traversal computes each square on demand; the original numbers remain unchanged.~پڑھتے وقت مربع بنتا ہے؛ اصل اعداد نہیں بدلتے۔','std::vector<int> v{1,2,3};\nauto squares=v|std::views::transform([](int x){return x*x;});\nfor(int x:squares)std::cout << x << " ";','vector ranges')
A('Exception safety guarantees','ایکسپشن میں حالت کی حفاظت','Memory & safety','Exception guarantees describe what remains true after an operation fails.','exception guarantee بتاتی ہے ناکامی کے بعد کون سی حالت درست رہتی ہے۔','The basic guarantee preserves invariants and avoids resource leaks.~بنیادی ضمانت اصول اور وسائل درست رکھتی ہے۔|The strong guarantee preserves the prior observable state if the operation fails.~مضبوط ضمانت ناکامی پر پرانی حالت رکھتی ہے۔|A common pattern is to prepare a new value first, then commit with a non-throwing operation.~پہلے نئی قدر تیار، پھر نہ پھینکنے والے عمل سے تبدیلی کریں۔','std::string original="old";\nstd::string replacement="new";\noriginal.swap(replacement);\nstd::cout << original;','string')
A('The rule of zero','زیرو کا اصول','Memory & safety','The rule of zero recommends classes whose members manage resources without custom special members.','زیرو اصول میں ارکان وسائل سنبھالتے ہیں اور دستی special members نہیں لکھتے۔','Choose value-owning members such as vector and string.~vector اور string جیسے مالک ارکان لیں۔|Let generated copy, move and destruction compose those members correctly.~خودکار copy، move اور destruction انہیں صحیح چلاتے ہیں۔|Write custom special members only when the class truly implements a lower-level ownership policy.~دستی عمل صرف حقیقی خاص ملکیت کے لیے لکھیں۔','Notebook a{{"one","two"}};\nNotebook b=a;\nstd::cout << b.pages.size();','vector string','struct Notebook{std::vector<std::string> pages;};')
A('The one-definition rule','ایک تعریف کا اصول','13. Program organization','The ODR governs how entities may be defined within and across translation units.','ODR ایک اور کئی translation units میں تعریفوں کے اصول دیتا ہے۔','An ordinary non-inline function generally needs one program definition.~عام non-inline فنکشن کی پروگرام میں ایک تعریف چاہیے۔|Headers can provide declarations that multiple source files include.~ہیڈر کے اعلان کئی سورس استعمال کر سکتے ہیں۔|Inline functions and templates have specific multiple-definition allowances only when the required consistency rules hold.~inline اور template کی کئی تعریفیں صرف یکسانیت کے اصول کے تحت ہیں۔','std::cout << twice(5);','', 'inline int twice(int x){return 2*x;}')
A('CMake targets','سی میک ٹارگٹ','Design & tools','A CMake target describes a build output and its source files, requirements and dependencies.','CMake ٹارگٹ آؤٹ پٹ، سورس اور ضروری تعلقات بیان کرتا ہے۔','Create a CMakeLists.txt with a project and add_executable for your sources.~project اور add_executable کے ساتھ بلڈ فائل بنائیں۔|Set language features on the target using target_compile_features rather than global ad-hoc flags.~ٹارگٹ پر زبان کی ضرورت طے کریں۔|Configure with cmake -S . -B build, then build with cmake --build build in a local project.~مقامی منصوبے میں پہلے configure پھر build کریں۔','std::cout << "CMake builds this source into a target.";')
A('Assertions & invariants','شرط اور مستقل اصول','Design & tools','An assertion checks a programmer assumption during enabled runtime checks.','assert فعال runtime جانچ میں پروگرامر کا فرض دیکھتا ہے۔','Use assert for internal assumptions that should already be true.~اندرونی درست ہونے والے فرض پر assert لگائیں۔|A false assertion terminates the program rather than performing normal user-error recovery.~غلط شرط پروگرام روکتی ہے، عام صارف کی خرابی نہیں سنبھالتی۔|NDEBUG can remove assertions, so never put required side effects or validation only inside assert.~NDEBUG اسے ہٹا سکتا ہے، ضروری کام صرف assert میں نہ رکھیں۔','int size=3;\nassert(size>0);\nstd::cout << "Invariant holds";','cassert')
A('Strategy pattern','سٹریٹیجی پیٹرن','Design & tools','Strategy makes an algorithm replaceable through a common interface.','Strategy مشترک انٹرفیس سے الگورتھم بدلنے دیتا ہے۔','Keep the surrounding workflow independent of a specific operation.~باقی کام خاص الگورتھم سے الگ رکھیں۔|Pass a callable that supplies the chosen behavior.~مطلوبہ عمل callable میں دیں۔|Swapping the callable changes behavior without modifying the workflow.~callable بدلنے سے باقی کوڈ بدلے بغیر عمل بدلتا ہے۔','auto multiply=[](int a,int b){return a*b;};\nstd::cout << calculate(3,4,multiply);','functional','int calculate(int a,int b,const std::function<int(int,int)>& fn){return fn(a,b);}')
A('Factory functions','فیکٹری فنکشن','Design & tools','A factory function centralizes how an object is created and returned.','فیکٹری فنکشن آبجیکٹ بنانے کا طریقہ ایک جگہ رکھتا ہے۔','Move creation decisions out of callers.~بنانے کے فیصلے caller سے الگ کریں۔|Return a value or explicit owning pointer so lifetime responsibility is clear.~قدر یا واضح مالک پوائنٹر واپس دیں۔|Callers use the product without repeating construction details.~caller بنانے کی تفصیل دہرائے بغیر آبجیکٹ استعمال کرتا ہے۔','auto p=makeCounter(5);\nstd::cout << p->value;','memory','struct Counter{int value;};\nstd::unique_ptr<Counter> makeCounter(int start){return std::make_unique<Counter>(Counter{start});}')
A('Deadlocks','ڈیڈ لاک','Concurrency','Deadlock occurs when threads wait cyclically for resources that cannot be released while waiting.','deadlock میں تھریڈ ایک دوسرے کے ایسے وسائل کا انتظار کرتے ہیں جو آزاد نہیں ہو پاتے۔','Two threads acquiring mutexes in opposite orders can create circular waiting.~الٹی لاک ترتیب چکر والا انتظار بنا سکتی ہے۔|Acquire multiple mutexes consistently or use a deadlock-avoiding multi-lock operation.~ترتیب یکساں یا مناسب multi-lock عمل رکھیں۔|Avoid calling unknown blocking code while holding locks; a lock helper cannot solve every wait cycle.~لاک میں نامعلوم انتظار والا کوڈ نہ چلائیں؛ ہر چکر خود حل نہیں ہوتا۔','std::mutex a,b;\n{std::scoped_lock locks(a,b);std::cout << "Acquired together";}','mutex')
A('Data races','ڈیٹا ریس','Concurrency','A data race involves unsynchronized conflicting accesses to ordinary memory, with at least one write.','data race میں بغیر ہم آہنگی ٹکرانے والی عام میموری رسائی ہوتی ہے، کم از کم ایک لکھنا ہے۔','Identify memory shared by concurrent execution paths.~مشترک میموری پہچانیں۔|Use a common mutex or suitable atomic operations for every conflicting access.~ہر ٹکرانے والی رسائی ایک mutex یا مناسب atomic سے کریں۔|A race-free program can still have logical race conditions; protect the whole required invariant.~data race نہ ہو تب بھی منطق کی race ہو سکتی ہے؛ پورا اصول بچائیں۔','std::atomic<int> n{0};\nstd::jthread a([&]{++n;}),b([&]{++n;});\na.join();b.join();\nstd::cout << n.load();','atomic thread')
